18.         output.Age = input.Age;
19.         output.Income = input.Income;
20.         output.Region = input.Region;
21.         output.PurchaseHistory = input.PurchaseHistory;
22.         output.Churned = string.Equals(input.ChurnedRaw, "Yes", StringComparison.OrdinalIgnoreCase);
23.     },
24.     contractName: null);
25. 
26. var dataView = mappingPipeline.Fit(rawData).Transform(rawData);
27. var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2, seed: 42);
28. 
29. var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
30.     .Append(mlContext.Transforms.Concatenate("Features",
31.         nameof(CustomerData.Age),
32.         nameof(CustomerData.Income),
33.         "RegionEncoded",
34.         nameof(CustomerData.PurchaseHistory)))
35.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
36.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
37.         labelColumnName: nameof(CustomerData.Churned),
38.         featureColumnName: "Features"));
39. 
40. var model = pipeline.Fit(split.TrainSet);
41. 
42. // Evaluate — guard against tiny test sets with no positive class
43. var predictions = model.Transform(split.TestSet);
44. try
