 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // --- Train and save the model at startup ---
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

 var rawData = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(
     dataPath, hasHeader: true, separatorChar: ',');

 // Map "Yes"/"No" strings to a boolean label
 var mappingPipeline = mlContext.Transforms.CustomMapping<CustomerDataRaw, CustomerData>(
     (input, output) =>
     {
         output.Age = input.Age;
         output.Income = input.Income;
         output.Region = input.Region;
         output.PurchaseHistory = input.PurchaseHistory;
         output.Churned = string.Equals(input.ChurnedRaw, "Yes", StringComparison.OrdinalIgnoreCase);
     },
     contractName: null);

 var dataView = mappingPipeline.Fit(rawData).Transform(rawData);
 var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2, seed: 42);

 var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(CustomerData.Age),
         nameof(CustomerData.Income),
         "RegionEncoded",
         nameof(CustomerData.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: nameof(CustomerData.Churned),
         featureColumnName: "Features"));

 var model = pipeline.Fit(split.TrainSet);

 // Evaluate — guard against tiny test sets with no positive class
 var predictions = model.Transform(split.TestSet);
 try
 {
     var metrics = mlContext.BinaryClassification.Evaluate(predictions,
         labelColumnName: nameof(CustomerData.Churned));
     Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, " +
                       $"Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
 }
 catch (ArgumentOutOfRangeException)
 {
     Console.WriteLine("Warning: Test set too small for meaningful metrics. Add more data.");
 }

 var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
 mlContext.Model.Save(model, dataView.Schema, modelPath);

 // Register the pooled prediction engine (thread-safe for web use)
 builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapGet("/", () => "Churn Predictor API — POST to /predict");

 app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool,
                          CustomerRequest req) =>
 {
     var input = new CustomerData
     {
